class OrdersModule {                        // one instance per table
public:
    explicit OrdersModule(TableDataGateway& gw) : gw_(gw) {}
    std::vector<OrderRow> overdue(const Date& as_of) const {
        return gw_.query<OrderRow>("select id, due, total from orders where due < ?", as_of);
    }
    Money total(const std::vector<OrderRow>& rows) const;   // set-oriented rule
private:
    TableDataGateway& gw_;
};
